export const OFFICER_FRAGMENT_SOURCES=Object.freeze(Object.keys(FRAGMENT_TRANSLATIONS.en));
const SOURCES=OFFICER_FRAGMENT_SOURCES.slice().sort((a,b)=>b.length-a.length);
const WORD=/[\p{L}\p{N}]/u;
function boundary(text,position,length,phrase){
 const before=position>0?text[position-1]:'';
 const after=position+length<text.length?text[position+length]:'';
 const first=phrase[0],last=phrase[phrase.length-1];
 return !(before&&WORD.test(before)&&WORD.test(first)) &&
        !(after&&WORD.test(after)&&WORD.test(last));
}
export function translateOfficerFragments(source,lang='de'){
 if(lang==='de'||!FRAGMENT_TRANSLATIONS[lang]||typeof source!=='string'||source.length>2000)return source;
 let result=source;
 for(const german of SOURCES){
  const translated=FRAGMENT_TRANSLATIONS[lang][german];
  if(!translated||translated===german||!result.includes(german))continue;
  let offset=0;
  while(offset<result.length){
   const pos=result.indexOf(german,offset);
   if(pos<0)break;
   if(!boundary(result,pos,german.length,german)){offset=pos+german.length;continue}
   result=result.slice(0,pos)+translated+result.slice(pos+german.length);
   offset=pos+translated.length;
  }
 }
 return result;
}
